import numpy as np
from scipy.optimize import least_squares
t=df['t'].values; A=df['A'].values; y=df['dA_dt'].values
V=np.var(y)
T={'1':np.ones_like(t),'t':t,'sqrt':np.sqrt(t),'1/t':1/t}
G={'1':np.ones_like(A),'A':A,'A2':A**2,'sqrtA':np.sqrt(A)}
grid=np.round(np.arange(0.2,4.01,0.2),2)
for c in grid:
    T[f'exp(-{c}/t)']=np.exp(-c/t); T[f'sin({c}sqrt t)']=np.sin(c*np.sqrt(t)); T[f'exp(-{c}t)']=np.exp(-c*t)
    G[f'exp(-{c}A)']=np.exp(-c*A); G[f'exp(-{c}A2)']=np.exp(-c*A**2); G[f'sin({c}A)']=np.sin(c*A)
names=[];cols=[];spec=[]
for kt,vt in T.items():
    for kg,vg in G.items():
        names.append(kt+' * '+kg); cols.append(vt*vg); spec.append((kt,kg))
M=np.column_stack(cols); M=M/np.linalg.norm(M,axis=0)
beam=[([],np.zeros(0))]
for step in range(4):
    newb=[]
    for sel,_ in beam:
        if sel:
            Q,_=np.linalg.qr(M[:,sel])
            r=y-Q@(Q.T@y); Mo=M-Q@(Q.T@M)
        else:
            r=y.copy(); Mo=M
        nrm=np.sum(Mo**2,axis=0)+1e-12
        score=(Mo.T@r)**2/nrm
        score[sel]=-1
        top=np.argsort(-score)[:6]
        for j in top:
            newb.append((sel+[int(j)], score[j]))
    # dedupe and keep best by residual of full lstsq
    uniq={}
    for s,_ in newb:
        key=tuple(sorted(s))
        if key not in uniq:
            c,_,_,_=np.linalg.lstsq(M[:,list(key)],y,rcond=None)
            uniq[key]=np.mean((y-M[:,list(key)]@c)**2)/V
    items=sorted(uniq.items(), key=lambda kv: kv[1])[:8]
    beam=[(list(k),v) for k,v in items]
    print('step',step,'best %.3e'%items[0][1], [names[i] for i in items[0][0]])
print('beam final:')
for k,v in beam[:4]:
    print('%.3e'%v, [names[i] for i in k])

